import{_ as r,l as i,o as a,c as s,v as t,p as l,x as o,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"最后贷款人","description":"","frontmatter":{"title":"最后贷款人","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/lender-of-last-resort.md","filePath":"econ/lender-of-last-resort.md","lastUpdated":1789023840000}'),h={name:"econ/lender-of-last-resort.md"};function c(B,e,m,A,u,_){const n=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=t('<h1 id="最后贷款人" tabindex="-1">最后贷款人 <a class="header-anchor" href="#最后贷款人" aria-label="Permalink to &quot;最后贷款人&quot;">​</a></h1><div class="epigraph"><p>恐慌时，中央银行应对好抵押品自由放贷，并收取惩罚性利率。</p><footer>—— 据 Bagehot, Lombard Street, 1873 整理</footer></div><p><a href="/econ/rtgs-payments">上一课</a>（支付系统与 RTGS）。<a href="/econ/reserve-endogenous-money">准备金、乘数与内生货币</a>。平时准备金迁就结算，存款由贷款创造；本课缺口是恐慌：人人要把 inside money 换成 outside money 时，谁按什么规则提供那笔高能货币。不重推 <a href="/econ/diamond-dybvig">Diamond–Dybvig</a> 的双均衡，只把它当作需要被停掉的坏均衡。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>序贯兑付一旦进入挤兑，有偿付能力的银行也会因为资产无法在 \\(t=1\\) 按面值变现而耗尽准备金。若央行袖手，清算折扣把流动性问题做成破产，坏均衡实现。若央行无条件给所有负债保兑，又把偿付能力缺口社会化，激励在平时加杠杆。缺口因此不是「要不要救银行」，而是：最后贷款（liquidity）与资本注入（solvency）必须分开写，规则要让耐心存款人愿意等到 \\(t=2\\)，同时不把资不抵债的机构当流动性问题处理。</p><p>Bagehot 的市场是十九世纪的伦敦汇票市场，不是当代的准备金走廊，但问题同构：货币市场的弹性在恐慌中消失，唯一还能创造 outside money 的机构必须充当弹性本身。</p><p><span class="marginnote">有偿付能力：按持有到期的价值，资产覆盖负债。流动性不足：无法在不承受火灾出售折扣的前提下，立即支付到期或可提取负债。挤兑把第二项变成对第一项的检验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Bagehot 规则三句，对应三个激励。第一，自由放贷：数量上满足需求，使耐心者相信队列会停。这是对 Diamond–Dybvig 坏均衡的删除，类似存款保险，但抵押在央行而不是财政的名义担保。第二，惩罚性利率：让不慌的机构不愿把央行当便宜的常规融资，减少平时对最后贷款人的依赖。第三，好抵押：把窗口限制在有偿付能力的借款人，迫使真正资不抵债的机构走处置而不是贴现。</p><p>当代操作把「好抵押」写成合格抵押品清单与估值折扣（haircut），把「惩罚利率」写成相对政策利率的罚息或 stigma。走廊体制下，最后贷款人往往是贴现窗口或紧急流动性便利；数量宽松是另一套工具，属于<a href="/econ/zlb-unconventional">零下限</a>，本课不把 QE 写成 Bagehot。</p>',10)),(a(),l(E,null,{default:o(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E6%8C%A4%E5%85%91%3A%20%E8%A6%81%20outside%20money%22%5D%20--%3E%20LOLR%5B%22%E6%9C%80%E5%90%8E%E8%B4%B7%E6%AC%BE%E4%BA%BA%22%5D%0A%20%20LOLR%20--%3E%20FREE%5B%22%E8%87%AA%E7%94%B1%E6%94%BE%E8%B4%B7%3A%20%E5%81%9C%E6%8E%89%E5%9D%8F%E5%9D%87%E8%A1%A1%22%5D%0A%20%20LOLR%20--%3E%20PEN%5B%22%E6%83%A9%E7%BD%9A%E5%88%A9%E7%8E%87%3A%20%E9%9D%9E%E5%B8%B8%E8%A7%84%22%5D%0A%20%20LOLR%20--%3E%20COL%5B%22%E5%A5%BD%E6%8A%B5%E6%8A%BC%3A%20%E7%AD%9B%E5%81%BF%E4%BB%98%E8%83%BD%E5%8A%9B%22%5D%0A%20%20COL%20--%3E%20RESOLVE%5B%22%E8%B5%84%E4%B8%8D%E6%8A%B5%E5%80%BA%E8%B5%B0%E5%A4%84%E7%BD%AE%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与内生货币的衔接：恐慌中乘数的因果暂时反转——不是 \\(H\\) 决定 \\(D\\)，而是 \\(D\\) 要兑换 \\(H\\)，若 \\(H\\) 不增加，系统收缩。最后贷款人恢复平时的弹性，使准备金再次迁就结算。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是信念与抵押的同时操作。自由放贷改变耐心者对 \\(t=2\\) 偿付的信念，提取的战略互补被削弱。抵押与估值折扣则是筛选：银行愿意按折扣抵押的资产，透露它认为自己过得了到期。惩罚利率提高使用窗口的机会成本，使便利成为偏离均衡路径上的工具，而不是日常的廉价资本替代——资本替代正是下一课 <a href="/econ/basel-capital">巴塞尔</a> 要禁止用流动性解决的问题。</p><p>时间不一致在这里已经露头：危机中「自由」的压力极大，事后把坏资产也收进抵押品的诱惑对应<a href="/econ/time-inconsistency">承诺</a>。Bagehot 把规则写在事前，正是为了限制这种权变。Kydland–Prescott 的附录对照不在本课展开。</p><h3 id="窗口、保险与暂停的分工" tabindex="-1">窗口、保险与暂停的分工 <a class="header-anchor" href="#窗口、保险与暂停的分工" aria-label="Permalink to &quot;窗口、保险与暂停的分工&quot;">​</a></h3><p>存款保险改变耐心者的支付，使其不必跑到央行窗口。暂停兑付直接关掉序贯服务。最后贷款人介于两者之间：银行仍营业、仍兑付，但资产暂时换成央行负债。三者都可以删坏均衡，激励不同。保险把信用风险转给保险基金；暂停把流动性风险丢回存款人的等待；窗口把流动性风险转给央行，信用风险仍应由资本与抵押挡住。混用三者——例如用窗口给资不抵债的机构无限额、无抵押——等于把 LOLR 做成隐蔽的资本注入。</p><p><span class="marginnote">Bagehot 的「惩罚利率」在利率已经接近零时不好用。罚息相对的是当时的市场利率，不是一个永恒的百分数。ZLB 下的紧急便利是主干非常规政策的对象。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>最后贷款人不是资本监管，也不是对股东的救助。把股权价值保全写成「流动性支持」，会破坏好抵押这一句。跨境银行使抵押品与最终贷款人的币种可能错配：不可能三角下，本币 LOLR 不能无限制提供外币流动性，外汇互换是另一套安排。本课不写巴塞尔风险权重，不写 MM 对银行股本成本的含义。</p><p>也不要把 2008 年之后的一切非常规工具都贴上 Bagehot：购买长期证券、对资不抵债机构的注资，超出「好抵押上的短期贷款」。那些是财政与货币政策的交界，分别在非常规政策与财政课。</p><p>本课默认央行能发行被挤兑者接受的 outside money。若挤兑的是外币负债，本币窗口不够，要回到<a href="/econ/impossible-trinity">不可能三角</a>下的储备与互换。那不是 Bagehot 原文的伦敦英镑市场，不要把一句「自由放贷」跨币种滥用。</p><p>后课默认：流动性支持按 Bagehot 三句操作，与资本注入分家。下一课把亏损顺序写成巴塞尔比率，不再把窗口当股本替代。跨境与外币挤兑回到开放宏观的储备约束，不在本课用「自由放贷」一笔带过。</p><p>窗口、保险、暂停都能删坏均衡，激励不同。混用窗口给资不抵债机构，等于隐蔽注资。</p><p>本币 LOLR 不能无限制提供外币流动性。不可能三角下，外币挤兑要储备或互换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>挤兑要把 inside money 换成 outside money；弹性必须由能发行后者的机构提供。</li><li>Bagehot：自由、惩罚利率、好抵押——删坏均衡、限道德风险、分清偿付。</li><li>流动性支持不是资本；下一课才把股本写成硬约束。</li><li>出处：Bagehot, <em>Lombard Street</em>；Diamond and Dybvig 1983 的政策含义。</li></ul>',16))])}const b=r(h,[["render",c]]);export{D as __pageData,b as default};
